import functools


def shout(func):
    @functools.wraps(func)
    def wrapper(text):
        return func(text).upper() + "!"
    return wrapper


def shout_report(names):
    @shout
    def greet(name):
        return "hi " + name

    results = [greet(n) for n in names]
    return [results, greet.__name__]

import functools


def count_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0          # fresh meter per decorated function
    return wrapper


def echo_report(script):
    @count_calls
    def echo(x):
        return x * 2

    before = echo.calls
    outs = [echo(x) for x in script]
    return [before, outs, echo.calls]

import functools


def memoize(func):
    """Cache func's results in a plain dict on the wrapper.

    Exposes .calls (times the wrapper was invoked) and .misses
    (times the wrapped function actually ran).
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        wrapper.calls += 1
        if key not in wrapper.cache:
            wrapper.misses += 1
            wrapper.cache[key] = func(*args, **kwargs)
        return wrapper.cache[key]
    wrapper.cache = {}
    wrapper.calls = 0
    wrapper.misses = 0
    return wrapper


def cost_report(script):
    @memoize
    def cost_of(n):
        return 3 * n + 1

    results = [cost_of(n) for n in script]
    return [results, cost_of.calls, cost_of.misses]
